// OZVOR fail-closed contract (B12, Codex D01, 23/09).
// Execution 2757 (23/09) and 2662 (19/09): the Leads API answered
// { error: 'unauthorized', code: 'INVALID_API_KEY' }, Pick Next Lead yielded 0
// items, and n8n reported Succeeded. A credential problem must FAIL the
// run and reach a human; an empty queue is a legitimate no-op; only a
// lead with an id goes on.
const out = [];
for (const item of $input.all()) {
  const res = item.json;
  const status = Number(res.statusCode ?? res.status ?? 0);
  const body = res.body ?? res;
  const code = String(body?.code ?? body?.error ?? '').toUpperCase();
  if (status === 401 || status === 403 || code.includes('INVALID_API_KEY') || code.includes('UNAUTHORIZED')) {
    throw new Error(`LEADS_AUTH_FAILED status=${status} code=${code || 'none'} — fix the Leads API credential in n8n; nothing was sent`);
  }
  if (status >= 500) {
    throw new Error(`LEADS_UNAVAILABLE status=${status} — Leads service error; nothing was sent`);
  }
  if (status !== 200) {
    throw new Error(`LEADS_UNEXPECTED status=${status} — contract violated; nothing was sent`);
  }
  const leads = Array.isArray(body?.leads) ? body.leads : Array.isArray(body) ? body : body?.lead ? [body.lead] : [];
  for (const lead of leads) {
    if (!lead || !lead.id) continue; // a lead without an id is not eligible
    out.push({ json: { lead, reservedAt: new Date().toISOString() } });
  }
}
// Empty: a valid no-op. The IF below stops the run quietly.
return out.length ? out : [{ json: { empty: true } }];

// A Hermes answer of { ok:true, started:true } is an ACCEPTED job, not a
// draft (Codex D09: execution 2760 ended 'Succeeded' in 528 ms on exactly
// that). Only ok=true with a non-empty output is a draft.
const res = $input.first().json;
const body = res.body ?? res;
if (body?.ok !== true || typeof body?.output !== 'string' || !body.output.trim()) {
  throw new Error(`DRAFT_NOT_PRODUCED ok=${body?.ok} started=${body?.started ?? 'n/a'} — accepted is not drafted; nothing was sent`);
}
return [{ json: { lead: $('Contract: auth error fails, empty is no-op').first().json.lead, draft: body.output, engine: body.engine_used ?? 'unknown' } }];

